package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.change.*;
import cn.mop.domain.change.ChangeNoticeDraftRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
/** Isolated boundaries only; actual PG/OIDC/CSRF HTTP checks are separate. */
class ChangeNoticeDraftControllerTest {
    static final String ACTOR="76000000-0000-4000-8000-000000000001",TENANT="76000000-0000-4000-8000-000000000002",ID="76000000-0000-4000-8000-000000000003",ASSET="76000000-0000-4000-8000-000000000004",OTHER="76000000-0000-4000-8000-000000000005";
    PlatformRepository platform;ChangeNoticeDraftRepository plans;ChangeNoticeDraftController controller;ObjectMapper mapper=new ObjectMapper();
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);plans=mock(ChangeNoticeDraftRepository.class);controller=new ChangeNoticeDraftController(platform,plans);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",7,true)));when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(call->{((Runnable)call.getArgument(6)).run();return ((Supplier<?>)call.getArgument(7)).get();});when(plans.get(any(),any())).thenReturn(row(1,false,draft()));when(plans.create(any(),any())).thenAnswer(call->row(1,false,call.getArgument(1)));when(plans.update(any(),any(),anyLong(),any())).thenAnswer(call->row(2,false,call.getArgument(3)));when(plans.archive(any(),any(),anyLong())).thenReturn(row(2,true,draft()));when(plans.restore(any(),any(),anyLong())).thenReturn(row(3,false,draft()));}
    Access access(){return new Access(ACTOR,TENANT,7,"change-notice-test");}
    MockHttpServletRequest request(String method){var r=new MockHttpServletRequest(method,"/api/v1/change-notice-drafts");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","change-notice-test");r.addHeader("Idempotency-Key","change-notice-test-key");return r;}
    ChangeNoticeDraft draft(){return new ChangeNoticeDraft(UUID.fromString(TENANT),UUID.fromString(ACTOR),null,"合成报备草稿",Instant.parse("2026-10-05T16:00:00Z"),null,List.of(UUID.fromString(ASSET)));}
    Snapshot row(long version,boolean archived,ChangeNoticeDraft d){var t=Instant.parse("2026-10-04T08:00:00.123Z");return new Snapshot(ID,TENANT,version,d,archived,ACTOR,t,t,t);}
    ObjectNode input(){var n=mapper.createObjectNode().put("expected_version",0).put("change_summary","合成报备草稿").put("planned_start_at","2026-10-05T16:00:00Z").putNull("planned_end_at").putNull("ticket_id");n.putArray("asset_ids").add(ASSET);return n;}
    static Map<?,?> data(Object r){return (Map<?,?>)((Map<?,?>)r).get("data");}
    @Test void createProjectsTenantAndApplicantFromSessionAndNeverApproves(){var out=data(controller.write(null,"CREATE",input(),request("POST")));assertEquals(TENANT,out.get("tenant_id"));assertEquals(ACTOR,out.get("applicant_id"));assertNull(out.get("approval_status"));assertNull(out.get("automatic_p3_decision"));assertEquals(false,out.get("effective"));assertEquals(false,out.get("alert_suppression_allowed"));assertEquals(false,out.get("device_execution_allowed"));assertNull(out.get("planned_end_at"));assertEquals("CONFIG_PENDING",out.get("approval_workflow_status"));verify(plans).authorizeCurrentAccess(access(),null);verify(plans).create(access(),draft());}
    @Test void unknownTenantExecutionAndSecretFieldsAreRejected(){for(String field:List.of("tenant_id","applicant_id","approval_status","automatic_p3_decision","alert_suppression_allowed","effective","command","password","access_key","approved")){var n=input().put(field,"SYNTHETIC_SECRET");assertEquals(400,assertThrows(DomainException.class,()->controller.write(null,"CREATE",n,request("POST"))).status);}verify(plans,never()).create(any(),any());}
    @Test void allInputFieldsIncludingExplicitNullsAndIntentAreRequired(){for(String f:List.of("expected_version","change_summary","asset_ids","planned_start_at","ticket_id","planned_end_at")){var n=input();n.remove(f);assertThrows(DomainException.class,()->controller.write(null,"CREATE",n,request("POST")));}}
    @Test void inputTypesDuplicatesAndStrictTimeFailBeforeWrite(){for(var value:List.of(input().put("planned_start_at",3),input().put("ticket_id","not-a-uuid"),input().put("planned_start_at","2026-10-05T16:00:00.0001Z"),input().put("planned_end_at",3),input().put("change_summary","\u00a0"),input().put("expected_version",0.0),input().put("planned_end_at","2026-10-05T16:00:00Z"))){assertThrows(DomainException.class,()->controller.write(null,"CREATE",value,request("POST")));}var duplicate=input();duplicate.withArray("asset_ids").add(ASSET);assertThrows(DomainException.class,()->controller.write(null,"CREATE",duplicate,request("POST")));var empty=input();empty.withArray("asset_ids").removeAll();assertThrows(DomainException.class,()->controller.write(null,"CREATE",empty,request("POST")));}
    @Test void targetLimitAndUnicodeBoundsDoNotTruncate(){var huge=input();for(int i=0;i<1000;i++)huge.withArray("asset_ids").add(new UUID(2,i).toString());assertThrows(DomainException.class,()->controller.write(null,"CREATE",huge,request("POST")));assertThrows(DomainException.class,()->controller.write(null,"CREATE",input().put("change_summary","😀".repeat(2001)),request("POST")));var okay=input().put("change_summary","😀".repeat(2000));assertEquals("😀".repeat(2000),data(controller.write(null,"CREATE",okay,request("POST"))).get("change_summary"));}
    @Test void updateRequiresPositiveBoundedExpectedVersion(){for(long n:new long[]{-1,0,9007199254740990L})assertThrows(DomainException.class,()->controller.write(ID,"UPDATE",input().put("expected_version",n),request("PATCH")));var out=data(controller.write(ID,"UPDATE",input().put("expected_version",1),request("PATCH")));assertEquals(2L,out.get("version"));verify(plans).update(access(),ID,1,draft());}
    @Test void archiveAndRestoreAcceptVersionOnlyAndCannotChangeDefinition(){for(String action:List.of("ARCHIVE","RESTORE")){assertThrows(DomainException.class,()->controller.write(ID,action,input().put("expected_version",1),request("POST")));controller.write(ID,action,mapper.createObjectNode().put("expected_version",1),request("POST"));}verify(plans).archive(access(),ID,1);verify(plans).restore(access(),ID,1);}
    @Test void replayCallsAuthorizationAndReturnsOriginalWithoutExecutingAgain(){doAnswer(call->{((Runnable)call.getArgument(6)).run();return Map.of("original",true);}).when(platform).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());assertEquals(true,data(controller.write(ID,"ARCHIVE",mapper.createObjectNode().put("expected_version",1),request("POST"))).get("original"));verify(plans).authorizeCurrentAccess(access(),ID);verify(plans,never()).archive(any(),any(),anyLong());}
    @Test void hashIgnoresObjectKeyOrderButBindsTargetOrderNullAndExpectedVersion(){var a=input();a.withArray("asset_ids").add(OTHER);var reordered=mapper.createObjectNode();var keys=new ArrayList<String>();a.fieldNames().forEachRemaining(keys::add);Collections.reverse(keys);for(String k:keys)reordered.set(k,a.get(k));controller.write(null,"CREATE",a,request("POST"));controller.write(null,"CREATE",reordered,request("POST"));var changed=a.deepCopy();changed.withArray("asset_ids").removeAll().add(OTHER).add(ASSET);controller.write(null,"CREATE",changed,request("POST"));controller.write(null,"CREATE",a.deepCopy().put("planned_end_at","2026-10-06T00:00:00Z"),request("POST"));controller.write(ID,"UPDATE",a.deepCopy().put("expected_version",1),request("PATCH"));var hashes=ArgumentCaptor.forClass(String.class);verify(platform,times(5)).idempotentAuthorized(any(),any(),any(),any(),hashes.capture(),anyLong(),any(),any());var h=hashes.getAllValues();assertEquals(h.get(0),h.get(1));for(int i=2;i<5;i++)assertNotEquals(h.get(0),h.get(i));}
    @Test void listReturnsMetadataOnlyAndPairedBoundedCursor(){when(plans.list(eq(access()),eq(16),isNull(),isNull())).thenReturn(Collections.nCopies(16,row(1,false,draft())));var out=data(controller.list(request("GET")));assertEquals(true,out.get("has_more"));assertEquals(20,out.get("page_size_limit"));var items=(List<?>)out.get("items");assertEquals(15,items.size());assertFalse(((Map<?,?>)items.get(0)).containsKey("asset_ids"));assertFalse(((Map<?,?>)items.get(0)).containsKey("change_summary"));assertEquals(ID,out.get("next_before_id"));verify(platform,never()).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());}
    @Test void getAndHistoryReturnUnpublishedExplicitTargets(){when(plans.get(access(),ID)).thenReturn(row(1,false,draft()));assertEquals(List.of(ASSET),data(controller.get(ID,request("GET"))).get("asset_ids"));var t=Instant.parse("2026-10-04T08:00:00Z");when(plans.history(access(),ID,16,null)).thenReturn(List.of(new Revision(ID,TENANT,1,"CREATE",draft(),false,ACTOR,t)));var out=data(controller.history(ID,request("GET")));assertNull(out.get("next_before_version"));var item=(Map<?,?>)((List<?>)out.get("items")).get(0);assertNull(item.get("previous_version"));assertEquals(false,item.get("effective"));}
    @Test void queryDuplicatesUnknownKeysAndInvalidPageSizesAreRejected(){for(String key:List.of("tenant_id","enabled","execute")){var r=request("GET");r.addParameter(key,"true");assertThrows(DomainException.class,()->controller.list(r));}var duplicate=request("GET");duplicate.addParameter("page_size","10","15");assertThrows(DomainException.class,()->controller.list(duplicate));for(String size:List.of("1","100","20.0","01")){var r=request("GET");r.addParameter("page_size",size);assertThrows(DomainException.class,()->controller.list(r));}var half=request("GET");half.addParameter("before_id",ID);assertThrows(DomainException.class,()->controller.list(half));}
    @Test void mutationsRejectAnyQueryOrMissingIdempotencyKey(){var q=request("POST");q.addParameter("dry_run","true");assertThrows(DomainException.class,()->controller.write(null,"CREATE",input(),q));var noKey=request("POST");noKey.removeHeader("Idempotency-Key");assertThrows(DomainException.class,()->controller.write(null,"CREATE",input(),noKey));}
    @Test void currentRoleAndSessionGatePrecedePayloadParsing(){for(String role:List.of("viewer","msp","tadmin","unknown")){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,7,true)));var r=request("POST");r.setContent("{bad".getBytes(StandardCharsets.UTF_8));assertEquals(403,assertThrows(DomainException.class,()->controller.create(r)).status);}var anonymous=new MockHttpServletRequest();assertEquals(401,assertThrows(DomainException.class,()->controller.list(anonymous)).status);verifyNoInteractions(plans);}
    @Test void bodyRejectsDuplicateKeysTrailingDocumentsAndDeepNesting(){for(String s:List.of("{\"expected_version\":0,\"expected_version\":1}","{}{}","{\"a\":{\"b\":{\"c\":{\"d\":{\"e\":1}}}}}")){var r=request("POST");r.setContent(s.getBytes(StandardCharsets.UTF_8));assertEquals(400,assertThrows(DomainException.class,()->ChangeNoticeDraftController.body(r)).status);}}
    @Test void bodyByteAndTokenLimitsAre413WithoutTruncation(){var r=request("POST");r.setContent(new byte[ChangeNoticeDraftController.MAX_BODY_BYTES+1]);assertEquals(413,assertThrows(DomainException.class,()->ChangeNoticeDraftController.body(r)).status);var token=request("POST");token.setContent(("["+"null,".repeat(4000)+"null]").getBytes(StandardCharsets.UTF_8));assertEquals(413,assertThrows(DomainException.class,()->ChangeNoticeDraftController.body(token)).status);var streamed=new MockHttpServletRequest(){@Override public long getContentLengthLong(){return -1;}};streamed.setContent(new byte[ChangeNoticeDraftController.MAX_BODY_BYTES+1]);assertEquals(413,assertThrows(DomainException.class,()->ChangeNoticeDraftController.body(streamed)).status);}
    @Test void validRawBodyKeepsNullAndWhitespace(){var n=input().put("change_summary"," \n\t😀 ");var r=request("POST");r.setContent(n.toString().getBytes(StandardCharsets.UTF_8));assertEquals(n,ChangeNoticeDraftController.body(r));var fresh=request("POST");fresh.setContent(n.toString().getBytes(StandardCharsets.UTF_8));assertEquals(" \n\t😀 ",data(controller.create(fresh)).get("change_summary"));}
    @Test void optionalTicketReferenceAndKnownEndNeverImplyApproval(){var n=input().put("ticket_id",OTHER).put("planned_end_at","2026-10-06T00:00:00Z");var out=data(controller.write(null,"CREATE",n,request("POST")));assertEquals(OTHER,out.get("ticket_id"));assertEquals("2026-10-06T00:00:00Z",out.get("planned_end_at"));assertNull(out.get("approval_status"));assertEquals(false,out.get("approval_evidence_verified"));}
    @Test void updateRetainsOriginalApplicantInsteadOfRebindingToCurrentEditor(){var d=draft();var original=new ChangeNoticeDraft(d.tenantId(),UUID.fromString(OTHER),null,d.changeSummary(),d.plannedStartAt(),null,d.assetIds());when(plans.get(access(),ID)).thenReturn(row(1,false,original));var out=data(controller.write(ID,"UPDATE",input().put("expected_version",1),request("PATCH")));assertEquals(OTHER,out.get("applicant_id"));verify(plans).update(access(),ID,1,original);}

    @Test void excessZeroFractionIsRejectedWithoutTruncationOrRepositoryWrite(){for(String field:List.of("planned_start_at","planned_end_at"))for(String value:List.of("2026-10-06T00:00:00.0000Z","2026-10-06T00:00:00Z\n","2026-10-06T00:00:00Z\r\n"))assertEquals(400,assertThrows(DomainException.class,()->controller.write(null,"CREATE",input().put(field,value),request("POST"))).status);verify(plans,never()).create(any(),any());}

}
